from lib2to3 import pytree, fixer_base
from lib2to3.pgen2 import token
from lib2to3.fixer_util import Name, Call, is_tuple, Comma, Attr, ArgList
from libfuturize.fixer_util import touch_import_top

class FixRaise(fixer_base.BaseFix):
    BM_compatible = True
    PATTERN = b"\n    raise_stmt< 'raise' exc=any [',' val=any [',' tb=any]] >\n    "

    def transform(self, node, results):
        syms = self.syms
        exc = results[b'exc'].clone()
        if exc.type == token.STRING:
            msg = b'Python 3 does not support string exceptions'
            self.cannot_convert(node, msg)
            return
        else:
            if is_tuple(exc):
                while is_tuple(exc):
                    exc = exc.children[1].children[0].clone()

                exc.prefix = u' '
            if b'tb' in results:
                tb = results[b'tb'].clone()
            else:
                tb = None
            if b'val' in results:
                val = results[b'val'].clone()
                if is_tuple(val):
                    args = [c.clone() for c in val.children[1:-1]]
                    exc = Call(exc, args)
                elif val.type in (token.NUMBER, token.STRING):
                    val.prefix = u''
                    exc = Call(exc, [val])
                elif val.type == token.NAME and val.value == u'None':
                    pass
                else:
                    touch_import_top(u'future.utils', u'raise_', node)
                    exc.prefix = u''
                    args = [exc, Comma(), val]
                    if tb is not None:
                        args += [Comma(), tb]
                    return Call(Name(u'raise_'), args, prefix=node.prefix)
            if tb is not None:
                tb.prefix = b''
                exc_list = Attr(exc, Name(b'with_traceback')) + [ArgList([tb])]
            else:
                exc_list = [
                 exc]
            return pytree.Node(syms.raise_stmt, [
             Name(u'raise')] + exc_list, prefix=node.prefix)
